      "code": "void main(void)\n{\nint a[10];\nvoid input();\nvoid output();\nvoid max_min();\ninput(a,10);\nmax_min(a,10);\noutput(a,10);\n}\nvoid input(int *arr,int n)\n{\nint *p,i;\np=arr;\nprintf(\"please enter 10 integers:\\n\");\nfor(i=0;i<n;i++)\n/**********FOUND**********/\nscanf(\"%d\",p);\n}\nvoid max_min(int *arr,int n)\n{\nint *min,*max,*p,t;\nmin=max=arr;\nfor(p=arr+1;p<arr+n;p++)\n/**********FOUND**********/\nif(*p<*max)\nmax=p;\nelse if(*p<*min) min=p;\nt=*arr;*arr=*min;*min=t;\n/**********FOUND**********/\nif(max=arr) max=min;\nt=*(arr+n-1);\n*(arr+n-1)=*max;\n*max=t;\n}\nvoid output(int *arr,int n)\n{\nint *p,i;\np=arr;\nprintf(\"The changed array is:\\n\");\n/**********FOUND**********/\nwhile(i=0;i<n;i++)\nprintf(\"%3d\",*p++);\nprintf(\"\\n\");\n}",
