      "code": "#include \"conio.h\"\n#include \"stdio.h\"\nsortpb ( int n, int *a )\n{\n/**********FOUND**********/\nint i, j, p, t\nfor ( j = 0; j < n-1 ; j++ )\n{\np = j;\nfor ( i = j + 1; i < n ; i ++ )\n/**********FOUND**********/\nif ( a[p] > a[j] ) p = i;\n/**********FOUND**********/\nif ( p == j )\n{\nt = a[j];\na[j] = a[p];\na[p] = t;\n}\n}\n}\ndouble rnd ( )\n{\nstatic t = 29, c = 217, m = 1024, r = 0;\nr =( r*t + c )%m; return( ( double )r/m );\n}\ngetarr( int n, int *x )\n{\nint i;\nfor( i = 1; i <= n; i++, x++ ) *x =\n( int )( 50*rnd() );\n}\nputarr( int n, int *z )\n{\nint i;\nfor( i = 1; i <= n; i++, z++ )\n{\nprintf( \"%4d\", *z );\nif ( !( i%10 ) ) printf( \"\\n\" );\n}\nprintf(\"\\n\");\n}\nmain()\n{\nint aa[20], n;\nclrscr();\nprintf( \"\\nPlease enter an integer number\nbetween 5 and 20: \" );\nscanf( \"%d\", &n );\ngetarr( n, aa );\nprintf( \"\\n\\nBefore sorting %d numbers:\\n\",\nn ); putarr( n, aa );\nsortpb( n, aa );\nprintf( \"\\nAfter sorting %d numbers:\\n\", n );\nputarr( n, aa );\ngetch();\n}",
