      "stem": "【功能要求】从m 个学生的成绩中统计出高于和\n等于平均分的学生人数，\n此人数由函数值返回。平均分通过形\n参传回，输入学生成\n绩时，用-1 结束输入，由程序自动统\n计学生人数。\n例如：若输入8 名学生的成绩，输入形式\n如下：\n80.5 60 72 90.5 98 51.5 88 64 -1\n结果为：\nThe number of students :4\nAve = 75.56。\n【修改提示】在标有 /**********FOUND**********/ 的下方各行中找出错误并改正，不得增行或删行。",
