      "number": 15,
      "stem": "编写程序，实现【猴子吃桃】算法与功能。",
      "code": null,
      "options": null,
      "answer": "#include<stdio.h> \nvoid main() \n{ \n \nint x1,x2=1,day; \n \nfor(day=9;day>0;day--) \n \n{ \n \n \nx1=2*(x2+1); \n \n \nx2=x1; \n \n} \n \nprintf(\"第一天的桃子数:%d\\n\",x1); \n5.1 用π/4≈1-1/3+1/5-1/7+…公式求π 的值，直到某一项的绝对值小于10\n-6为止。 \n\n \n \n#include <stdio.h> \n#include <math.h> \nint main () \n{ \n   double PI=0.0,a=1.0,term=1.0; \n   int sign=1; \n   while(fabs(term)>=1e-6) \n   {  \n   PI+=term; \n       a=a+2; \n   sign=-sign; \n   term=sign/a; \n   } \n    PI=PI*4; \n   printf(\"PI=%10.8f\\n\",PI); \nreturn 0; \n} \n \n5.9 题目要求：用近似公式求：e≈1+1/1!+1/2!+1/3!+….+1/n!,使误差小于给定的ε，设ε=10-5。\n& \n#include<stdio.h> \n#include<math.h> \nvoid main() \n{ \n \nint i=1,q=1; \n \nfloat e=1,p; \n \nfor(i;fabs(p)>=1e-5;i++) \n \n{ \n \n \nq=i*q; \n \n \np=1.0/q; \n \n \ne=e+p; \n \n} \n \nprintf(\"e=%f\\n\",e); \n5.10 输入两个正整数m 和n,求其最大公约数和最小公倍数。 \n#include <stdio.h> \nvoid main() \n{ \n \nint m,n,i,j,k,g,t; \n \nprintf(\"请输入两个正整数：\\n\"); \n \nscanf(\"%d,%d\",&m,&n); \n \nif(m<=n) \n \n{ \n \n \n \nk=m; \n \n    m=n; \n\n \n \n \n \nn=k; \n \n} \n \nfor(i=n;i>=0;i--) \n \n{ \n \n \nif((m%i==0)&&(n%i==0)) \n \n \n{ \n \n \n \n \ng=i; \n \n \n   break; \n \n \n} \n \n} \n \nfor(j=m;;j++) \n \n{ \n \n \nif((j%m==0)&&(j%n==0)) \n \n \n{ \n \n \n \nt=j; \n \n \n \nbreak; \n \n \n} \n \n} \n \nprintf(\"最大公约数：%d,最小公倍数：%d\",g,t); \n} \n \n} \n5.14 打印大小可变的菱形图案。 \n#include<stdio.h> \nvoid main() \n{ \n \nint i,j,k,l; \n \nprintf(\"enter max line:\"); /*输入最大行数,奇数*/ \n \n \nscanf(\"%d\",&j); \n \nfor (i=-j/2;i<=j/2;i++) \n \n{  \n \n \nif (i<0) l=-i; \n \n \nelse l=i; \n \n \nfor (k=0;k<l;k++) \n \n \n \nprintf(\" \"); /*输出每一行的空格*/ \n \n \nif (i>0)  \n \n \n \nl=-i; \n \n \nelse l=i; \n \n \nfor (k=0;k<(l+j/2)*2+1;k++) \n \n \n \nprintf(\"*\"); /*输出每一行的星号*/ \n \n \nprintf(\"\\n\"); /*输出第一行的回车*/ \n \n} \n} \n字母输出其后的。 \n\n \n \n#include<stdio.h> \nvoid main() \n{ \n \nchar ch; \n \nch=getchar(); \n \nwhile(ch!='!') \n \n{ \n \n \n \nif(ch>='A'&&ch<='Z'||(ch>='a'&&ch<='z')) printf(\"%c\",ch+1); \n \n \nelse printf(\"%c\",ch); \n \n \nch=getchar(); \n \n} \n \nputchar('\\n'); \n} \n变换大小写 \n#include<stdio.h> \n \nvoid main() \n \n{ \n \n \nchar ch; \n \n \nch=getchar(); \n \n \nwhile(ch!='!') \n \n \n{ \n \n \n \n \nif(ch>='A'&&ch<='Z') \n \n \n \n \nprintf(\"%c\",ch+32); \n \n \n \nelse if (ch>='a'&&ch<='z') \n \n \n \n \nprintf(\"%c\",ch-32); \n \n \n \nelse \n \n \n \n \nprintf(\"%c\",ch); \n \n \n \nch=getchar(); \n \n \n} \n\n \n \n \n \nputchar('\\n'); \n \n} \n#include<stdio.h> \n \nint main() \n \n{ \n \n    int n,i,j,a[30][30],sum=0; \n \n    scanf(\"%d\",&n); \n \n    for(i=0;i<n;i++) \n \n    { \n \n        for(j=0;j<n;j++) \n \n        { \n \n            scanf(\"%d\",&a[i][j]); \n \n        } \n \n    } \n \n    for(i=0;i<n;i++) \n \n    { \n \n        for(j=0;j<n;j++) \n \n        { \n \n            if(i>=j) \n \n            { \n \n                sum=sum+a[i][j]; \n \n            } \n \n\n \n \n        } \n \n    } \n \n    printf(\"%d\",sum); \n \n    return 0; \n \n} \n \n版权声明：本文为博主",
